package in.kabadiwala.connect.service; import in.kabadiwala.connect.integration.PaymentProvider; import in.kabadiwala.connect.model.*; import in.kabadiwala.connect.repository.*; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.*; @Service public class PaymentService {private final PaymentRepository payments;private final TransactionRepository txs;private final LotRepository lots;private final PaymentProvider provider;private final NotificationService notes;private final AuditService audit;public PaymentService(PaymentRepository p,TransactionRepository t,LotRepository l,PaymentProvider pp,NotificationService n,AuditService a){payments=p;txs=t;lots=l;provider=pp;notes=n;audit=a;} public Map<String,Object> initiate(String actor,String txid){var t=txs.findAll().stream().filter(x->x.transactionId.equals(txid)).findFirst().orElseThrow(()->new IllegalArgumentException("Transaction not found"));if(!t.recyclerId.equals(actor))throw new IllegalArgumentException("Access denied");var existing=payments.findTopByTransactionIdOrderByCreatedAtDesc(txid);if(existing.isPresent()&&List.of("INITIATED","SUCCESS").contains(existing.get().status))throw new IllegalArgumentException("Payment already initiated");var p=new Payment();p.paymentId="PAY-"+UUID.randomUUID().toString().substring(0,10).toUpperCase();p.transactionId=txid;p.amount=t.finalAmount;p.provider=provider.name();p.status="INITIATED";p=payments.save(p);var details=provider.initiate(p);if(details.get("id")!=null){p.providerOrderId=details.get("id").toString();payments.save(p);}audit.log(actor,"PAYMENT_UPDATED","PAYMENT",p.paymentId,"PENDING","INITIATED",Map.of());return Map.of("payment",p,"provider",details);} public Payment confirm(String actor,String paymentId,String providerPaymentId,String signature,boolean manualConfirmed){var p=payments.findByPaymentId(paymentId).orElseThrow();var t=txs.findAll().stream().filter(x->x.transactionId.equals(p.transactionId)).findFirst().orElseThrow();if(!t.recyclerId.equals(actor))throw new IllegalArgumentException("Access denied");boolean ok=provider.name().equals("MANUAL")?manualConfirmed:provider.verify(p.providerOrderId,providerPaymentId,signature);if(!ok){p.status="FAILED";payments.save(p);throw new IllegalArgumentException("Payment could not be verified");}p.status="SUCCESS";p.providerPaymentId=providerPaymentId;payments.save(p);t.paymentStatus="SUCCESS";t.status="COMPLETED";t.completedAt=Instant.now();t.receiptId="RCT-"+UUID.randomUUID().toString().substring(0,10).toUpperCase();txs.save(t);var l=lots.findByLotId(t.lotId).orElseThrow();l.status=LotStatus.COMPLETED;lots.save(l);notes.send(t.collectorId,"PAYMENT_SUCCESS","TRANSACTION",t.transactionId,Map.of("amount",t.finalAmount));notes.send(t.collectorId,"TRANSACTION_COMPLETED","TRANSACTION",t.transactionId,Map.of());audit.log(actor,"TRANSACTION_COMPLETED","TRANSACTION",t.transactionId,"ACTIVE","COMPLETED",Map.of());return p;}}
